const MAP=new Map(DATA.map(r=>[String(r[0]),r]));
const $=id=>document.getElementById(id);
const input=$('roll'),err=$('err'),res=$('result'),again=$('again'),check=$('check');
function showErr(t){err.textContent=t;err.classList.add('show')}
function clearErr(){err.classList.remove('show')}
function lookup(){
  clearErr();res.classList.remove('show');
  let v=input.value.replace(/\s+/g,'').trim();
  if(!v){showErr('Please enter your roll number.');input.focus();return}
  if(!/^\d+$/.test(v)){showErr('Roll number must contain digits only.');input.focus();return}
  v=v.replace(/^0+/,'');
  const r=MAP.get(v);
  if(!r){showErr('Roll number not found. Please verify your roll number and try again.');return}
  $('rRoll').textContent=r[0];$('rScore').textContent=r[1];$('rRank').textContent='#'+r[2];
  void res.offsetWidth;res.classList.add('show');
  check.style.display='none';input.disabled=true;again.style.display='block';
  res.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function reset(){
  res.classList.remove('show');clearErr();input.disabled=false;input.value='';
  check.style.display='block';again.style.display='none';input.focus();
}
check.addEventListener('click',lookup);
again.addEventListener('click',reset);
input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();lookup()}});
input.addEventListener('input',()=>{clearErr()});
